    try:
        # Split the morse code into words
        words = morse_code.strip().split('/')
        decoded = ''
        for word in words:
            # Split word into characters
            chars = word.strip().split()
            # Decode each character
            for char in chars:
                if char in MORSE_CODE_DICT:
                    decoded += MORSE_CODE_DICT[char]
            decoded += ' '
        return decoded.strip()
    except Exception as e:
        print(f"Error decoding morse: {e}")
        return morse_code

def extract_rsa_params(text):
    try:
        # Try to find RSA parameters
        params = text.split()
        if len(params) < 3:
            return None

        # Look for TiA9, e=, and c=
        Ti = None
        e = None
        c = None

        for p in params:
            if 'TIA9' in p.upper():
                try:
                    Ti = int(p.split('A9')[1])
                except:
                    continue
            elif 'E=' in p.upper():
