                   '1': '.----', '2': '..---', '3': '...--', '4': '....-', '5': '.....', '6': '-....',
                   '7': '--...', '8': '---..', '9': '----.', ' ': ' '}

# Create reverse morse dictionary
MORSE_REVERSE = {v: k for k, v in MORSE_CODE_DICT.items()}

def morse_decode(message):
    try:
        message = message.strip()
        words = message.split('/')
        decoded = ''
        for word in words:
            chars = word.strip().split()
            for char in chars:
                if char in MORSE_REVERSE:
                    decoded += MORSE_REVERSE[char]
                else:
                    log.warning(f"Unknown morse char: {char}")
            decoded += ' '
        return decoded.strip()
    except Exception as e:
        log.error(f"Morse decode error: {e}")
        return None

def try_base64(s):
    try:
        s = s.strip()
        decoded = base64.b64decode(s).decode()
        # Check if the decoded string looks valid
        if all(32 <= ord(c) <= 126 for c in decoded):
            return decoded
        return None
    except:
