    try:
        decoded = codecs.decode(s, 'rot13')
        # Check if decoding actually changed something
        if decoded != s:
            return decoded
        return None
    except:
        return None

def is_rsa_format(s):
    return all(x in s for x in ['n =', 'e =', 'ct ='])

