    try:
        n = int(re.search(r'n\s*=\s*(\d+)', s).group(1))
        e = int(re.search(r'e\s*=\s*(\d+)', s).group(1))
        ct = int(re.search(r'ct\s*=\s*(\d+)', s).group(1))
        return n, e, ct
    except:
        return None, None, None

